package com.example.demo.controller; import com.example.demo.model.Product; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/products") public class ProductController { private final List<Product> productList=new ArrayList<>(); private long currentId=1; public ProductController(){productList.add(new Product(currentId++,"Laptop",75000));productList.add(new Product(currentId++,"Smartphone",25000));} @GetMapping public ResponseEntity<List<Product>> getAllProducts(){return new ResponseEntity<>(productList,HttpStatus.OK);} @GetMapping("/{id}") public ResponseEntity<?> getProductById(@PathVariable Long id){return productList.stream().filter(p->p.getId().equals(id)).findFirst().<ResponseEntity<?>>map(p->new ResponseEntity<>(p,HttpStatus.OK)).orElse(new ResponseEntity<>("Product with ID "+id+" not found.",HttpStatus.NOT_FOUND));} @PostMapping public ResponseEntity<Product> createProduct(@RequestBody Product p){p.setId(currentId++);productList.add(p);return new ResponseEntity<>(p,HttpStatus.CREATED);} @PutMapping("/{id}") public ResponseEntity<?> updateProduct(@PathVariable Long id,@RequestBody Product x){for(Product p:productList)if(p.getId().equals(id)){p.setName(x.getName());p.setPrice(x.getPrice());return new ResponseEntity<>(p,HttpStatus.OK);}return new ResponseEntity<>("Failed to update: Product ID "+id+" does not exist.",HttpStatus.NOT_FOUND);} @DeleteMapping("/{id}") public ResponseEntity<String> deleteProduct(@PathVariable Long id){return productList.removeIf(p->p.getId().equals(id))?new ResponseEntity<>("Product deleted successfully.",HttpStatus.OK):new ResponseEntity<>("Cannot delete: Product ID "+id+" not found.",HttpStatus.NOT_FOUND);} }